// The Windows right-click menu is native; its ellipsis counterpart is HTML.
// Localize known command IDs only, including fixed labels under Copy and Split.
if (template.some(row => row.id === 'delete') &&
    template.some(row => row.id === 'mark-read' || row.id === 'restore')) {
    const labels = new Map([["Rename", "重命名"], ["Mark Read", "标为已读"], ["Mark Unread", "标为未读"], ["Restore", "还原"], ["Delete Permanently", "永久删除"], ["Return to Inbox", "移回收件箱"], ["Resolve", "标记为已处理"], ["Pin", "置顶"], ["Unpin", "取消置顶"], ["Pin This Conversation", "置顶此对话"], ["Unpin This Conversation", "取消置顶此对话"], ["Pin Entire Project", "置顶整个项目"], ["Unpin Project", "取消置顶项目"], ["View Debug", "查看调试信息"], ["Copy", "复制"], ["Split", "拆分"], ["Fork", "创建分支"], ["Share", "分享"], ["Archive", "归档"], ["Delete", "删除"], ["Stop", "停止"], ["Conversation Name", "对话名称"], ["Conversation ID", "对话 ID"], ["Workspace Name", "工作区名称"], ["Worktree Name", "工作树名称"], ["Project Name", "项目名称"], ["Split Right", "向右拆分"], ["Split Down", "向下拆分"], ["Replace with New", "替换为新对话"], ["Remove from Split", "移出拆分视图"], ["Move to Group", "移至分组"], ["New Group", "新建分组"], ["Remove from Group", "从分组移除"]]);
    const fixed = new Set(['rename','pin','pin-workspace','mark-read','inbox-resolve','view-debug',
        'copy','fork','split','share','archive','delete','restore','stop','move-to-group']);
    for (const row of template) {
        if (fixed.has(row.id) && labels.has(row.label)) row.label = labels.get(row.label);
        for (const child of row.submenu || []) {
            if ((row.id === 'copy' || row.id === 'split' || child.id === 'group-new' ||
                 child.id === 'group-remove') && labels.has(child.label)) child.label = labels.get(child.label);
        }
    }
}
